L(1,'early',[(1922,'Образование СССР'),(1924,'Первая Конституция СССР')],[
('От гражданской войны к объединению','После Гражданской войны на территории бывшей империи существовали советские республики с собственными правительствами. Их связывали общая партия, военное командование, транспорт и разрушенное хозяйство. Объединение должно было закрепить сотрудничество и облегчить восстановление. Однако вопрос заключался также в том, сохранят ли республики самостоятельное государственное положение или будут включены в Российскую республику на правах автономий.'),
('Спор о форме союза','Сталин предлагал проект автономизации: другие республики входили бы в РСФСР. Ленин выступил за союз формально равноправных республик. Это различие имело политическое значение после имперской политики и национальных конфликтов. При этом обе позиции предполагали сохранение единой партийной власти. За спором о юридической форме стояли также интересы республиканских руководителей, стремившихся защитить собственные полномочия и местные учреждения.'),
('Учреждение нового государства','30 декабря 1922 года Первый съезд Советов СССР утвердил Декларацию и Договор об образовании Союза. Учредителями стали РСФСР, Украинская и Белорусская советские республики и Закавказская федерация. Конституция 1924 года оформила союзные органы и распределение компетенций. Внешняя политика, оборона и важнейшие хозяйственные вопросы переходили на союзный уровень; республиканские органы продолжали существовать в установленной общей системе.'),
('Федерация и партийный центр','Федерация означает объединение территориальных государственных образований с разделением полномочий. В СССР республикам предоставлялось формальное право выхода, но отдельной действующей процедуры его осуществления первоначально не создали. Единство партии ограничивало самостоятельность республиканских решений. Одновременно политика коренизации поддерживала местные языки, подготовку национальных кадров и развитие культурных учреждений. Поэтому союз сочетал централизацию с институциональным оформлением национальных различий.'),
('Долговременные последствия','Образование СССР создало рамку общей индустриализации, социальной политики и внешнего представительства. Оно также закрепило территориальные границы и республиканские государственные институты, значение которых позднее изменилось. Нельзя объяснять распад 1991 года только формулировкой о выходе: между учреждением и распадом лежали десятилетия политических решений. Важен вопрос, как декларации равенства соотносились с реальным влиянием союзного руководства и опытом разных народов.')
], 'Юридическое равноправие республик и фактическая централизация не исключали друг друга: они относились к разным уровням устройства государства. Для проверки нужно сравнивать конституционный текст с порядком партийных назначений.',('Какие образования учредили СССР в декабре 1922 года?',['РСФСР, УССР, БССР и Закавказская федерация','Только РСФСР и УССР','Все пятнадцать позднейших республик'],'РСФСР, УССР, БССР и Закавказская федерация'),('Почему единая партия ограничивала федеративную самостоятельность?','Республиканские руководители подчинялись общим партийным решениям','Республики не имели никаких органов власти'))
L(3,'early',[(1924,'Смерть Ленина'),(1927,'Поражение объединённой оппозиции'),(1929,'Разгром правой оппозиции')],[
('Наследование без установленного порядка','После смерти Ленина в январе 1924 года партия не имела процедуры передачи его личного авторитета одному преемнику. Формально решения принимались коллективными органами. Реальная борьба шла за большинство в руководстве, контроль над назначениями и право объяснять ленинское наследие. Болезнь Ленина уже прежде усилила значение аппаратных связей; поэтому конфликт нельзя свести к внезапному соперничеству на похоронах.'),
('Сила партийного аппарата','Сталин был генеральным секретарём с 1922 года. Эта должность давала влияние на подбор и продвижение кадров, хотя сама по себе ещё не делала его единоличным правителем. Троцкий обладал известностью организатора Красной армии, Зиновьев и Каменев опирались на крупные партийные организации. Их ресурсы различались: личная популярность, административные связи и поддержка делегатов не были одним и тем же.'),
('Изменение коалиций','Сначала Сталин, Зиновьев и Каменев выступали против Троцкого. Затем Зиновьев и Каменев сблизились с прежним противником, образовав объединённую оппозицию. Сталин в этот период сотрудничал с Бухариным и сторонниками продолжения НЭПа. Позднее разногласия о хлебозаготовках и темпах индустриализации раскололи и этот союз. Победитель менял партнёров по мере того, как менялись угрозы его позиции и хозяйственный курс.'),
('Политические споры и правила борьбы','Участники обсуждали мировую революцию, строительство социализма в одной стране, отношения с крестьянством и внутрипартийную демократию. Но запрет фракций, установленный ещё в 1921 году, позволял представлять организованное несогласие как нарушение дисциплины. Сочетание идеологических обвинений и организационных мер сужало допустимые формы критики. Исключение из партии означало для оппозиционера потерю не только политического влияния, но часто и профессиональных возможностей.'),
('Почему итог не был предрешён','К концу десятилетия Сталин устранил главные организованные группы соперников. Однако будущие массовые казни не следовали автоматически из каждого спора 1920-х годов: это отдельный этап ужесточения режима. Историки различают аппаратную стратегию, личные качества участников и социальные ожидания партийного большинства. Для объяснения результата важно проследить последовательность союзов, а не приписывать Сталину неизменный полный контроль с момента назначения секретарём.')
], 'Изменение союзов показывает, что раскол руководства касался одновременно власти и хозяйственной стратегии. Участник мог поддержать один курс, а затем потерять влияние при его пересмотре.',('Какой ресурс давала Сталину должность генерального секретаря?',['Влияние на подбор партийных кадров','Право наследования престола','Независимую от партии частную армию'],'Влияние на подбор партийных кадров'),('Почему запрет фракций помогал подавлять оппозицию?','Организованную критику представляли нарушением партийной дисциплины','Он гарантировал всем группам равное эфирное время'))
L(4,'early',[(1922,'Сталин становится генеральным секретарём'),(1936,'Принятие Конституции СССР'),(1938,'Завершение пика Большого террора')],[
('От партийной монополии к личной власти','К концу 1920-х годов политическая конкуренция вне правящей партии была подавлена, а внутрипартийная оппозиция разгромлена. Сталин использовал эту систему, расширяя собственное влияние через назначения, хозяйственные кампании и органы безопасности. Формирование диктатуры было процессом, а не одним юридическим актом. Партийные органы продолжали работать, но возможности открыто оспаривать позицию руководителя постепенно становились опаснее.'),
('Аппарат и номенклатура','Номенклатурой называли перечни должностей, назначение на которые контролировали партийные органы; этим же словом позднее обозначали управленческий слой. Руководитель зависел от вышестоящих инстанций в карьере, жилье и доступе к ресурсам. Такая система обеспечивала проведение общих решений, но поощряла осторожность, личную лояльность и благоприятную отчётность. Инициатива сохранялась, однако её пределы задавались политическими сигналами сверху.'),
('Конституция и практика','Конституция 1936 года провозгласила широкие социальные и политические права, всеобщее избирательное право и новую организацию высших органов. Одновременно независимая партийная конкуренция отсутствовала, цензура ограничивала печать, а репрессии лишали людей правовой защиты. Читать конституцию следует как важный нормативный документ и образ желаемого порядка, сопоставляя его с механизмами реального принятия решений, а не автоматически принимая норму за повседневную действительность.'),
('Мобилизация и террор','Государство требовало ускоренного выполнения хозяйственных задач и политической бдительности. Пропаганда связывала успехи с руководителем, а трудности могла объяснять вредительством и заговорами. Массовые операции органов безопасности создавали атмосферу угрозы для очень разных групп населения. Террор был государственным насилием с решениями, исполнителями и жертвами; он не являлся просто стихийным результатом взаимных доносов или универсальным условием любого промышленного развития.'),
('Культ и поведение людей','Культ личности представлял Сталина главным источником мудрости и успехов. Портреты, юбилеи и переработанная история партии закрепляли этот образ. Отношение населения было неодинаковым: убеждённость, страх, расчёт и надежда могли сочетаться. Внешнее участие в ритуале не доказывает внутреннего согласия каждого участника. Для оценки режима важно видеть одновременно институты, ответственность руководства и разнообразные способы приспособления, сопротивления и сохранения частной жизни.')
], 'Публичные гарантии прав могли укреплять привлекательность государства, даже когда практики власти этим гарантиям противоречили. Проверять нужно не только наличие нормы, но и доступность независимого способа защиты.',('Что в советской системе означала номенклатура?',['Должности под контролем партийных назначений и связанный с ними управленческий слой','Все жители промышленных городов','Независимый конституционный суд'],'Должности под контролем партийных назначений и связанный с ними управленческий слой'),('Почему благоприятная отчётность могла скрывать реальные трудности?','Карьера руководителя зависела от оценки вышестоящего аппарата','Любая статистика по определению совершенно точна'))
L(5,'early',[(1928,'Начало первой пятилетки'),(1932,'Завершение первой пятилетки'),(1935,'Начало стахановского движения')],[
('Почему выбрали ускорение','Советское руководство стремилось сократить промышленное отставание и создать оборонную базу в условиях ожидания новой войны. Спор шёл о темпе, источниках накопления и отношениях с деревней. В конце 1920-х годов верх взял курс на ускоренное строительство тяжёлой промышленности. Приоритет военных и производственных задач означал, что потребительские нужды населения часто уступали инвестициям в металл, машины и энергетику.'),
('Пятилетний план как способ управления','Первая пятилетка началась в 1928 году. Центральные органы задавали показатели выпуска, строительства и распределения ресурсов. Предприятия зависели от назначенных поставок и административных решений. План помогал концентрировать усилия, но завышенные задания и несогласованность смежных отраслей вызывали перебои. Официальное сообщение о выполнении плана необходимо сравнивать с качеством продукции, затратами и тем, какие первоначальные показатели позднее менялись.'),
('Стройки и рабочая сила','Магнитогорск, Днепрогэс и новые машиностроительные предприятия стали символами преобразований. Использовались закупленные технологии и помощь иностранных специалистов. Миллионы выходцев из деревни осваивали промышленный труд, часто без достаточной подготовки. Возникали рабочие общежития и новые города, но жильё, канализация и снабжение отставали от строительства цехов. Принудительный труд заключённых также использовали, однако им нельзя объяснить всю советскую промышленность.'),
('Социальная цена и возможности','Индустриализация открывала путь к профессии, образованию и продвижению для ранее сельских семей. Одновременно она сопровождалась нехваткой товаров, тяжёлыми условиями труда и давлением на работников. Изъятие сельскохозяйственных ресурсов было связано с насильственной коллективизацией и катастрофой деревни. Промышленный рост поэтому нельзя оценить только тоннами стали: необходимо учитывать питание, здоровье, свободу передвижения и распределение издержек между разными социальными группами.'),
('Итоги и спор об альтернативах','СССР создал крупную промышленную базу, имевшую важное значение в будущей войне. Из этого результата не следует, что каждый метод сталинской политики был необходим или эффективен. Историки обсуждают возможные темпы при продолжении более постепенного развития, качество планирования и потери от насилия. Альтернативный сценарий нельзя проверить как состоявшееся событие, но можно сравнивать реальные ресурсы, затраты и управленческие решения.')
], 'Рост выпуска и повышение благосостояния являются разными показателями. Если инвестиции увеличивались за счёт ограничения текущего потребления, промышленный успех мог сопровождаться ухудшением жизни отдельных групп.',('Какой сектор получил главный приоритет в первых пятилетках?',['Тяжёлая промышленность','Частный туристический бизнес','Производство предметов роскоши'],'Тяжёлая промышленность'),('Почему выполнение плана в тоннах не исчерпывает оценку индустриализации?','Оно не показывает качества продукции и социальных издержек','Промышленность не влияла на повседневную жизнь'))
L(8,'early',[(1920,'Культурные эксперименты начала десятилетия'),(1932,'Роспуск независимых художественных объединений'),(1934,'Первый съезд советских писателей')],[
('Образование как преобразование общества','Большевики связывали новое общество с массовой грамотностью, технической подготовкой и изменением повседневных привычек. Расширялись школы, рабочие факультеты и профессиональное обучение. Доступ к знаниям зависел также от происхождения и политических критериев. Равенство возможностей оставалось противоречивым: женщины и выходцы из бедных семей получали новые пути продвижения, но нехватка учителей, книг и помещений ограничивала результат, особенно вне крупных городов.'),
('Разнообразие двадцатых годов','В литературе, театре, кино и архитектуре сосуществовали разные направления. Конструктивисты искали функциональные формы жилья и общественных зданий, кинематографисты экспериментировали с монтажом, писатели спорили о революции и новом человеке. Это не означало полной свободы: цензура и политическое давление существовали с начала советской власти. Но пространство художественного поиска в 1920-е годы было шире, чем в период последующей жёсткой унификации.'),
('Поворот к единой системе','Постановление 1932 года перестроило литературно-художественные организации; вместо множества объединений создавались централизованные творческие союзы. На съезде писателей 1934 года закрепили социалистический реализм как нормативный метод. От искусства требовали понятности, воспитательной задачи и изображения движения к социалистическому будущему. Эти требования могли сочетаться с высоким мастерством, но ограничивали допустимые сюжеты и делали профессиональную судьбу зависимой от политического признания.'),
('Семья, религия и дисциплина','После ранних экспериментов в семейной политике государство усилило акцент на устойчивой семье, родительских обязанностях и дисциплине. Женская занятость расширялась, однако домашняя работа преимущественно оставалась на женщинах. Антирелигиозные кампании сопровождались закрытием храмов и преследованием верующих. При этом религиозные практики не исчезли: часть сохранялась в семье и местном сообществе, показывая пределы способности государства полностью перестроить частную жизнь.'),
('Достижения без единой оценки','Расширение грамотности, научных учреждений и культурной аудитории стало важным результатом эпохи. Одновременно репрессии, цензура и идеологические запреты разрушали творческие среды и человеческие судьбы. Не стоит выбирать между этими сторонами как взаимоисключающими версиями. Нужно уточнять, какие возможности получил конкретный человек, чем за них платил и какие темы оставались запретными. История культуры включает и официальные произведения, и вытесненные голоса.')
], 'Творческий союз мог одновременно давать издательские возможности, материальную поддержку и инструменты дисциплинарного контроля. Организационную поддержку культуры следует анализировать вместе с зависимостью художника от единственного заказчика.',('Как изменились художественные организации после решения 1932 года?',['Началось создание централизованных творческих союзов','Была отменена всякая цензура','Прекратились любые публикации'],'Началось создание централизованных творческих союзов'),('Почему рост женской занятости не устранял неравенство автоматически?','Домашние обязанности преимущественно продолжали выполнять женщины','Образование было полностью закрыто для женщин'))
L(9,'cold',[(1922,'Рапалльский договор'),(1934,'Вступление СССР в Лигу Наций'),(1939,'Пакт с Германией')],[
('Двойственность внешней политики','СССР стремился к дипломатическому признанию и торговым связям, продолжая поддерживать международное коммунистическое движение. Для иностранных правительств эти направления могли противоречить друг другу. Советской промышленности требовались технологии и кредиты, а руководству — безопасность границ. Поэтому отношения с капиталистическими странами нельзя описать только непрерывной враждой: переговоры, экономическое сотрудничество и идеологическое соперничество существовали одновременно, меняясь под воздействием конкретных угроз.'),
('Рапалло и признание','Договор с Германией в Рапалло в 1922 году стал важным шагом выхода из изоляции. Обе стороны после мировой войны имели сложные отношения с победителями. В последующие годы расширялось признание СССР другими государствами; Соединённые Штаты установили дипломатические отношения в 1933 году. Договорённости создавали возможности торговли, но не устраняли взаимного недоверия и разногласий о революционной деятельности за рубежом.'),
('Коллективная безопасность','После прихода нацистов к власти в Германии советское руководство усилило поиск соглашений против агрессии. В 1934 году СССР вступил в Лигу Наций, заключал договоры и выступал против политики уступок агрессорам. Однако доверие между Москвой, Лондоном и Парижем оставалось слабым. Их интересы и представления о гарантиях различались, а государства между Германией и СССР опасались утраты собственного суверенитета.'),
('Войны за пределами СССР','Советский Союз оказывал помощь Испанской республике во время гражданской войны. На Дальнем Востоке происходили вооружённые столкновения с японскими силами, включая бои у озера Хасан и на Халхин-Голе. Эти события показывали угрозу войны на разных направлениях. Их нельзя считать одной непрерывной кампанией: в каждом случае отличались участники, международные обязательства, масштабы вмешательства и непосредственные цели советского руководства.'),
('Поворот 1939 года','Переговоры СССР с Великобританией и Францией летом 1939 года не привели к военному соглашению. В августе Москва заключила договор о ненападении с нацистской Германией и секретный протокол о сферах интересов. Объяснение советских опасений не отменяет ответственности за последующие решения. Дипломатическую смену курса следует оценивать и по выигрышу времени для СССР, и по последствиям для Польши и других соседних государств.')
], 'Неудачу коллективной безопасности нельзя объяснить только одним отказом: действовали взаимное недоверие, разные гарантии и страх малых государств перед вводом чужих войск. Но конкретный пакт оставался выбором руководства.',('В каком году СССР вступил в Лигу Наций?',['1934','1922','1945'],'1934'),('Почему торговые связи не устраняли политического недоверия?','Экономическое сотрудничество сосуществовало с идеологическим соперничеством','Дипломатические отношения означали полное совпадение интересов'))
L(10,'cold',[(1939,'Нападение Германии на Польшу'),(1939,'Вступление советских войск в восточную Польшу'),(1940,'Разгром Франции')],[
('От европейского кризиса к войне','Вторая мировая война в Европе началась нападением нацистской Германии на Польшу 1 сентября 1939 года. Ему предшествовали разрушение ограничений Версальского порядка, агрессия против соседних государств и неудачи международного сдерживания. Пакт Германии с СССР снизил для Гитлера непосредственный риск войны на двух фронтах. Это был важный дипломатический фактор, однако решение начать вторжение принимало германское руководство.'),
('Польская кампания','Великобритания и Франция объявили войну Германии 3 сентября. Польская армия сопротивлялась, но оказалась в крайне тяжёлом положении. 17 сентября Красная армия вошла в восточные районы Польши. Советское правительство ссылалось на распад польского государства и защиту населения; эти заявления следует отличать от факта вторжения и раздела территории согласно договорённостям с Германией. Польское правительство продолжило деятельность в изгнании.'),
('Раздел и оккупационный порядок','Германия и СССР закрепили новую границу договором 28 сентября. На занятых территориях происходили аресты, перемещение населения и преобразование институтов. Режимы оккупации различались по целям и практикам, но для населения раздел означал потерю прежних правовых гарантий и угрозу насилия. Нацистская политика преследования евреев стала развиваться в условиях войны и захвата огромного числа людей под германский контроль.'),
('Расширение войны','После периода сравнительно ограниченных действий на западе Германия в 1940 году захватила Данию и Норвегию, затем разгромила Францию и заняла ряд других стран. Великобритания продолжила сопротивление. Успехи германской армии изменили баланс сил и советские расчёты безопасности. Нельзя переносить исход этих кампаний назад: в сентябре 1939 года участники ещё не знали ни будущего разгрома Франции, ни продолжительности всей войны.'),
('Советская позиция и последствия','СССР до июня 1941 года не воевал с Германией, поддерживал с ней экономические связи и расширял собственную территорию. Поэтому начальный европейский этап следует отличать от Великой Отечественной войны, начавшейся для СССР 22 июня 1941 года. Такая периодизация помогает увидеть положение жителей Польши, стран Балтии и Финляндии, чья военная история не укладывается только в советскую хронологию борьбы с нацизмом.')
], 'Термин «начало войны» зависит от масштаба рассмотрения: европейская война началась в 1939 году, а японская агрессия в Азии имеет более раннюю историю. В данном уроке обозначена именно европейская отправная точка.',('Какая дата обозначает начало Второй мировой войны в Европе?',['1 сентября 1939 года','22 июня 1941 года','9 мая 1945 года'],'1 сентября 1939 года'),('Почему нужно различать Вторую мировую и Великую Отечественную войны?','У них разные временные и географические рамки','Это два названия совершенно одинакового периода'))
L(11,'early',[(1939,'Начало войны с Финляндией'),(1940,'Аннексия стран Балтии'),(1941,'Начало германского вторжения')],[
('Расширение западных границ','После пакта с Германией СССР включил в свой состав восточные районы Польши, затем страны Балтии, Бессарабию и Северную Буковину. Эти процессы сопровождались военным давлением и преобразованием государственных институтов. Советское руководство объясняло действия укреплением безопасности и объединением родственных народов. Для оценки необходимо также учитывать принуждение, отсутствие свободного политического выбора и опыт населения, утратившего прежнее гражданство и государственный порядок.'),
('Война с Финляндией','30 ноября 1939 года советские войска напали на Финляндию после неудачи переговоров о границе и военных объектах. Ожидание быстрой победы не оправдалось: финская оборона, местность и недостатки подготовки Красной армии затянули войну. Мир марта 1940 года дал СССР территориальные приобретения, но Финляндия сохранила независимость. Кампания продемонстрировала необходимость улучшать взаимодействие войск, снабжение и подготовку командиров.'),
('Подготовка к большой войне','Советское государство увеличивало вооружённые силы, военное производство и выпуск новой техники. Перевооружение требовало обучения, ремонтной базы, связи и перестройки организационных структур. Наличие большого количества танков не означало готовности каждого соединения к бою. Одновременно военные реформы и расширение армии создавали нагрузку на командование. Репрессии против офицеров также нанесли ущерб, но ими нельзя объяснить все проблемы подготовки.'),
('Разведка и решения руководства','Советское руководство получало многочисленные сообщения об угрозе германского нападения. Они различались по точности дат, источникам и достоверности. Сталин опасался провокации и стремился отсрочить столкновение, что влияло на оценку предупреждений и готовность войск. Признание противоречивости информации не снимает ответственности за решения. Важно различать знание о вероятной войне вообще и своевременное приведение конкретных частей в боевую готовность.'),
('Итог предвоенного периода','Передвижение границы на запад увеличило территорию СССР, но новые оборонительные позиции и коммуникации оставались недостаточно освоенными. На присоединённых землях население пережило советизацию, аресты и депортации, что влияло на отношение к власти. СССР вступил в войну с огромными ресурсами и серьёзными уязвимостями. Объяснение катастрофы 1941 года требует соединять стратегические ошибки, качество управления и особенности германского наступления.')
], 'Территориальный выигрыш и военная готовность не совпадают: новые расстояния могут дать время, но требуют дорог, укреплений и управляемых соединений. Изменение границы не является само по себе достаточным показателем безопасности.',('Что показала советско-финляндская война руководству Красной армии?',['Проблемы подготовки и взаимодействия войск','Отсутствие необходимости в снабжении','Полную готовность всех соединений к любой войне'],'Проблемы подготовки и взаимодействия войск'),('Почему количество новой техники не равно готовности армии?','Нужны обученные экипажи, ремонт, связь и снабжение','Техника никогда не влияет на боевые действия'))
L(13,'war',[(1941,'Операция «Тайфун»'),(1941,'Советское контрнаступление под Москвой')],[
('Столичное направление','К осени 1941 года германское командование рассчитывало разгромить советские силы на центральном направлении и овладеть Москвой. Столица была политическим символом, промышленным центром и крупным транспортным узлом. После тяжёлых летних поражений советская сторона испытывала недостаток подготовленных резервов. Однако длительное продвижение уже растянуло германские коммуникации и уменьшило возможности наступающих получать пополнение, технику и горючее в первоначальном темпе.'),
('Окружения и кризис обороны','Операция «Тайфун» началась в конце сентября — начале октября. Крупные советские группировки оказались окружены в районах Вязьмы и Брянска. Потери людей и управления создали угрозу столице. Оборона строилась с использованием новых рубежей, резервных частей и мобилизации населения. Эти события нельзя описывать только как спокойное выполнение заранее готового плана: командованию приходилось срочно реагировать на опасные прорывы и нехватку сил.'),
('Город перед угрозой захвата','В октябре часть учреждений эвакуировали, в Москве возникла паника, затем ввели осадное положение. Жители строили укрепления и участвовали в противовоздушной обороне. Парад 7 ноября имел большое символическое значение, однако устойчивость фронта обеспечивалась прежде всего боевыми действиями и снабжением. Решение Сталина остаться в столице поддерживало политический сигнал сопротивления, но не заменяло повседневную работу командиров, рабочих и транспортников.'),
('Предел наступления и ответный удар','В ноябре германские силы вновь продвинулись к Москве, но не смогли добиться её захвата. Сказывались сопротивление, потери, истощение снабжения и зимние условия. В начале декабря Красная армия перешла в контрнаступление, оттеснив противника от столицы. Резервы с востока имели значение, однако объяснение победы только «сибирскими дивизиями» или морозом скрывает общий масштаб советских усилий и германских проблем.'),
('Значение и ограничения победы','Под Москвой был сорван расчёт на завершение войны с СССР в одной короткой кампании. Победа укрепила уверенность советского общества и значение СССР для союзников. Но германская армия сохранила большую силу, а советские наступления начала 1942 года не достигли всех целей. Поэтому Московскую битву следует понимать как важный стратегический рубеж, сохраняя различие между отражением угрозы столице и окончательным исходом войны.')
], 'Погода воздействовала на обе армии, но их возможности готовиться к ней и получать зимнее снабжение различались. Природное условие становится историческим объяснением только вместе с анализом решений и ресурсов сторон.',('Какое главное стратегическое ожидание Германии сорвала оборона Москвы?',['Завершить войну с СССР короткой кампанией','Немедленно открыть фронт в Америке','Сохранить мирный договор без боевых действий'],'Завершить войну с СССР короткой кампанией'),('Почему нельзя объяснять исход битвы только морозом?','Нужно учитывать сопротивление, резервы, потери и снабжение обеих сторон','Погода существовала только на советской стороне'))
L(14,'socwar',[(1941,'Начало блокады Ленинграда'),(1943,'Прорыв блокады'),(1944,'Полное снятие блокады')],[
('Город в кольце','В сентябре 1941 года германские войска перерезали сухопутные связи Ленинграда с основной территорией СССР. Финские войска действовали к северу от города, усиливая общую изоляцию. Блокада стала частью войны на уничтожение: нацистское руководство не собиралось обеспечивать существование населения. Историю города необходимо рассматривать одновременно как военную оборону и как намеренное создание условий массовой гибели гражданских людей.'),
('Голодная зима','Зимой 1941–1942 годов резко сократилось питание, перестали нормально работать отопление, водоснабжение и транспорт. Голод соединялся с холодом и истощением; люди умирали дома, на работе и на улицах. Положение зависело от нормы снабжения, здоровья и помощи близких. Одна минимальная хлебная норма не описывает весь период блокады и все категории жителей. Для оценки смертности нужны временные и территориальные границы подсчёта.'),
('Ладога и эвакуация','Ладожское озеро обеспечивало ограниченную связь с внешним миром. По воде, а зимой по льду доставляли продовольствие и вывозили жителей. «Дорога жизни» подвергалась обстрелам и зависела от погоды и пропускной способности. Эвакуация спасала людей, но была тяжёлым испытанием для уже истощённых пассажиров. Её масштабы и доступность менялись: нельзя считать, что каждый человек мог покинуть город в любой момент.'),
('Работа и сохранение связей','В Ленинграде продолжали действовать предприятия, госпитали, учреждения культуры и городские службы. Люди поддерживали близких, вели дневники, сохраняли свидетельства преступления. Героические поступки не отменяют крайних форм распада социальных связей под действием голода. Важно избегать требования обязательного героизма от каждой жертвы. Выживание ребёнка, забота о больном и сохранение человеческого достоинства также относятся к истории сопротивления катастрофе.'),
('Прорыв, освобождение и память','В январе 1943 года операция «Искра» восстановила сухопутный коридор к городу, улучшив снабжение. Полностью блокаду сняли 27 января 1944 года. Поэтому прорыв и снятие являются разными событиями. После войны общественная память долго подчёркивала героизм, ограничивая разговор о некоторых сторонах голода и управления. Современное изучение соединяет военные документы, демографию и личные свидетельства, сохраняя внимание к ответственности организаторов блокады.')
], 'Понятия «прорыв» и «снятие» блокады обозначают разные изменения: появление коридора не устранило сразу угрозу обстрела и военное давление на город. Точная хронология необходима для понимания условий жизни населения.',('Чем январь 1943 года отличается от января 1944 года в истории блокады?',['В 1943 году блокаду прорвали, в 1944 году полностью сняли','В 1943 году блокада началась','В 1944 году город впервые окружили'],'В 1943 году блокаду прорвали, в 1944 году полностью сняли'),('Почему одинаковую хлебную норму нельзя приписывать всем жителям за весь период?','Нормы менялись во времени и различались по категориям снабжения','В блокаде не существовало системы распределения'))
L(16,'war',[(1943,'Начало операции «Цитадель»'),(1943,'Советские контрнаступления под Орлом и Белгородом')],[
('Выступ на линии фронта','После зимних боёв 1942–1943 годов вокруг Курска образовался выступ советского фронта. Германское командование намеревалось ударами с севера и юга окружить находившиеся там силы. Для СССР было важно сохранить инициативу после Сталинграда и не допустить нового крупного поражения. Стороны готовились несколько месяцев, что позволило советскому командованию создать глубоко эшелонированную оборону и сосредоточить резервы.'),
('План и подготовка обороны','Советское решение сочетало преднамеренную оборону с будущим наступлением. Минные поля, противотанковые районы и артиллерия должны были ослабить ударные группировки противника. Разведывательные сведения помогали оценить вероятное направление действий. Однако знание замысла не гарантировало лёгкого отражения атаки: требовались устойчивое управление и способность закрывать прорывы. Особенно важным было наличие резервов, которыми можно было усилить опасный участок без разрушения всего фронта.'),
('Июльское сражение','Операция «Цитадель» началась 5 июля 1943 года. Германское наступление встретило сильное сопротивление, но на отдельных направлениях продвинулось глубоко. Бои у Прохоровки 12 июля стали одним из самых известных эпизодов. Их прежние описания как однозначной танковой победы нуждаются в уточнении по документам. Значение всей битвы не зависит от сохранения преувеличенных утверждений о соотношении сил и потерях в одном столкновении.'),
('Переход к наступлению','Советские войска начали операции против орловской и затем белгородско-харьковской группировок. Германия не достигла цели окружения Курского выступа. Воздействовали советское сопротивление, исчерпание наступательных возможностей и общее положение Германии на других театрах. Поэтому важно различать прекращение «Цитадели», отдельные оборонительные бои и последующие советские наступления. Курская битва представляет цепь взаимосвязанных операций, а не один день массовой танковой атаки.'),
('Последствия и изучение','После летних боёв 1943 года стратегическая инициатива устойчиво переходила к Красной армии. Германия ещё могла проводить мощные местные контрудары, но всё хуже восполняла потери. Советские успехи открыли путь к дальнейшему освобождению территории. Историки уточняют масштабы потерь и результат отдельных эпизодов по журналам боевых действий и ремонтным документам. Подбитый танк, безвозвратно потерянная машина и погибший танкист являются разными показателями.')
], 'Тактический результат отдельного боя и стратегический исход кампании могут различаться. Уточнение неудачных действий советского соединения не отменяет срыва германского замысла, а позволяет понять реальный механизм общего успеха.',('Какую цель имела германская операция «Цитадель»?',['Окружить советские силы на Курском выступе','Захватить Ленинград через Ладогу','Открыть путь в Северную Африку'],'Окружить советские силы на Курском выступе'),('Почему подбитые танки нельзя автоматически считать безвозвратно потерянными?','Часть машин могла быть эвакуирована и восстановлена','Любой танк после попадания исчезает из учёта'))
L(17,'socwar',[(1941,'Создание Государственного комитета обороны'),(1941,'Массовая эвакуация предприятий'),(1943,'Рост военного производства')],[
('Перестройка хозяйства','После германского нападения государство подчинило производство и распределение задаче ведения войны. Созданный в июне 1941 года Государственный комитет обороны сосредоточил чрезвычайные полномочия. Требовалось одновременно снабжать фронт, перемещать заводы и поддерживать существование населения. Решения принимались централизованно, но исполнение зависело от инженеров, железнодорожников и местной администрации, действовавших в обстановке быстрого отступления и разрушения прежних хозяйственных связей.'),
('Заводы на востоке','Предприятия эвакуировали на Урал, в Поволжье, Сибирь, Казахстан и другие восточные районы. Станки нередко начинали работать в ещё не завершённых помещениях. Перемещение производства было не простой перевозкой оборудования: нужно было восстановить электроэнергию, поставки сырья, технологические связи и трудовые коллективы. Утраты и задержки были велики, однако сохранение промышленного ядра стало одним из важнейших условий продолжения войны после потери западных областей.'),
('Кто заменял ушедших на фронт','Женщины, подростки и пожилые люди занимали рабочие места мобилизованных. Удлинялся рабочий день, усиливалась трудовая дисциплина, ограничивалась возможность сменить предприятие. Патриотическая мотивация сочеталась с административным принуждением и борьбой за выживание. Для подростка завод означал участие в общем деле, но также раннее взросление, опасный труд и нарушение образования. Успех выпуска вооружения имел измеримую человеческую цену.'),
('Деревня и продовольствие','Сельское хозяйство потеряло значительную часть работников, техники и посевных площадей. Оставшиеся труженики обеспечивали государственные поставки в тяжёлых условиях. Личные подсобные хозяйства и огороды помогали выживанию. Карточная система распределяла ограниченное продовольствие, но питание различалось по профессии, территории и статусу. Официальная выдача не всегда покрывала потребности; семьи искали дополнительные ресурсы через обмен, родственников и неформальную помощь.'),
('Результат и ограничения мобилизации','К середине войны советская промышленность устойчиво обеспечивала крупные наступательные операции. Это объясняется эвакуацией, стандартизацией вооружения, обучением работников, внутренними ресурсами и союзными поставками. Представлять тыл как полностью бесконфликтное общество неверно: существовали истощение, нарушения, неравенство и жалобы. Его устойчивость была результатом напряжённого взаимодействия государства и населения, а не отсутствия трудностей или автоматической эффективности любого приказа сверху.')
], 'Высокий выпуск вооружения мог сочетаться с падением гражданского потребления. Чтобы оценить мобилизацию, нужно рассматривать эффективность для фронта и условия воспроизводства человеческих сил в тылу как связанные, но разные задачи.',('Почему эвакуация завода не сводилась к перевозке станков?',['Требовалось восстановить энергию, поставки и работу коллектива','Оборудование работало без людей и электричества','Все заводы были одинаковыми по устройству'],'Требовалось восстановить энергию, поставки и работу коллектива'),('Почему рост военного выпуска не означает роста благосостояния тыла?','Ресурсы направляли фронту, ограничивая гражданское потребление','Оружие непосредственно заменяло продовольствие'))
L(18,'socwar',[(1941,'Начало массовой оккупации советских территорий'),(1942,'Расширение партизанского движения'),(1944,'Освобождение большинства оккупированных областей')],[
('Цели захватчиков','Нацистская оккупация была частью войны на уничтожение и колониального переустройства востока. Захватчики изымали продовольствие, использовали принудительный труд, уничтожали евреев и преследовали другие группы населения. Военнопленных массово обрекали на голод и гибель. Разные оккупационные учреждения могли спорить о способах эксплуатации, но это не отменяло общей расовой иерархии и систематического насилия, направленного против жителей захваченных территорий.'),
('Повседневный выбор под угрозой','Оставшиеся жители искали пищу, работу и способы защитить семью. Работа при оккупационной администрации могла иметь разные формы: от вынужденного обслуживания коммунальных нужд до добровольного участия в репрессивных органах. Эти действия нельзя смешивать автоматически. Но давление обстоятельств не снимает ответственности за участие в убийствах и преследовании. Историку необходимо устанавливать конкретную роль человека, доступные альтернативы и степень принуждения по документам.'),
('Подполье и партизаны','Сопротивление включало подпольные группы, разведку, помощь пленным, саботаж и вооружённые партизанские соединения. Со временем усиливались связи партизан с советским командованием и снабжением. Успешные действия нарушали коммуникации противника и помогали фронту. При этом отношения с местными жителями зависели от дисциплины, продовольственных возможностей и политических конфликтов. Партизанская война была неодинаковой в разных районах и менялась по мере продвижения фронта.'),
('Карательные действия','Германские силы и вспомогательные формирования проводили массовые расправы под предлогом борьбы с партизанами. Уничтожение деревень и заложников было преступной политикой коллективного наказания. Называть погибших просто «побочным ущербом» означает скрывать намеренный характер насилия. Для изучения необходимы документы исполнителей, материалы расследований и свидетельства жителей; отдельная операция должна рассматриваться в рамках конкретного места, состава участвовавших сил и целей командования.'),
('После освобождения','Возвращение советской власти приносило прекращение нацистского террора, восстановление учреждений и возможность поиска близких. Одновременно начинались проверки поведения при оккупации; подозрение могло затрагивать людей с очень разными судьбами. Участников преступлений нужно отличать от тех, кто просто не смог эвакуироваться. Память о сопротивлении долго заслоняла сложность выживания и отдельные преследования. Полная история включает героизм, сотрудничество, принуждение и судьбы жертв геноцида.')
], 'Моральная оценка участия в преступлении требует установления действий, а не только места проживания. Жизнь на оккупированной территории сама по себе не доказывает ни сотрудничества с нацистами, ни принадлежности к сопротивлению.',('Почему проживание при оккупации не доказывает сотрудничества с захватчиками?',['Многие люди не могли уехать и пытались выжить','Все жители автоматически входили в подполье','Оккупация происходила только в пустых городах'],'Многие люди не могли уехать и пытались выжить'),('Почему расправы над заложниками нельзя объяснять обычным ведением боя?','Это намеренное коллективное наказание гражданских','Любое гражданское население является военной целью'))
EXTRA={
1:[('Разные народы и общая территория','Союзные границы проходили по землям со смешанным населением, сложной историей расселения и хозяйственных связей. Национальная республика поэтому не была государством только одной этнической группы. Внутри республик существовали автономии и национальные меньшинства, а принадлежность к территории не всегда совпадала с языком семьи. Коренизация могла расширять доступ местных жителей к управлению, но одновременно закрепляла административные категории национальности. Позднейшая политика не была простым продолжением 1922 года: централизация, репрессии и пересмотр национальных программ меняли содержание первоначальных обещаний. Для сравнения периодов необходимо различать существование республиканских учреждений и их способность самостоятельно определять политику.'),('Что доказывает союзный договор','Учредительный документ показывает, какие обязательства правительство провозглашало перед другими республиками и населением. Он не позволяет без дополнительных сведений определить степень добровольности объединения для каждого сообщества. Советские режимы утвердились в условиях революции и войн, поэтому переговоры руководителей нельзя автоматически считать свободным волеизъявлением всех жителей. В то же время союз нельзя описывать как полное отсутствие национальных институтов: они реально создавали школы, печать и административные кадры. Именно сочетание партийного единства с территориальным оформлением национальностей отличало советский вариант федерации и стало одним из долговременных наследий нового государства.')],
3:[('Ленинское наследие как политический ресурс','Предсмертные ленинские заметки содержали критические характеристики нескольких руководителей и предложение об изменении положения Сталина. Их обсуждение внутри партии не привело к открытой процедуре выбора преемника населением. Ссылки на Ленина использовали разные участники, называя именно свой курс верным продолжением революции. Поэтому последующая официальная версия победителя не может служить единственным описанием спора. Необходимо сопоставлять речи, переписку и организационные решения по времени их появления, чтобы отличать действительные позиции участников от обвинений, сформулированных уже после их поражения. Такое чтение показывает, как политическая память становилась инструментом текущей борьбы.'),('От исключения к преследованию','Поражение оппозиции в 1920-е годы обычно означало потерю должности, исключение, ссылку или вынужденное покаяние. В следующем десятилетии многие бывшие соперники Сталина были объявлены участниками преступных заговоров и уничтожены. Эти разные формы давления нужно различать, даже прослеживая их связь. Отказ от права на организованную критику облегчал дальнейшее насилие, но конкретные решения о следствии и казнях принимались позднее. Положение рядового партийца тоже менялось: голосование за большинство могло выражать убеждение, карьерный расчёт или страх изоляции. Установить личный мотив можно только по дополнительным свидетельствам, а не по одному факту голосования.')],
4:[('Местная власть и центр','Центральное руководство зависело от информации снизу и не могло лично контролировать каждое предприятие или деревню. Местные руководители переводили общие кампании в конкретные списки, задания и наказания. Иногда они просили увеличить ресурсы или пересмотреть показатели; иногда пытались скрыть провал, усиливая давление на подчинённых. Это не превращает диктатуру в свободную инициативу мест: рамки кампаний и право применять насилие задавались сверху. Но изучение исполнения помогает объяснить различия между регионами и механизм нарастания репрессий. Ответственность центральных организаторов и действия местных исполнителей являются связанными уровнями одной политической системы.'),('Публичность и скрытая информация','Печатная картина общества подчёркивала единство, успехи и мудрость руководителя. При этом внутренние сводки могли сообщать о недовольстве, нехватке продовольствия и хозяйственных сбоях. Разрыв между публичным и служебным сообщением важен для оценки осведомлённости власти. Нельзя считать, что отсутствие проблемы в газете означает её неизвестность руководству. Равным образом частное письмо не представляет автоматически настроения всей страны. Сопоставление разных каналов информации позволяет увидеть, какие трудности признавались внутри аппарата, как их объясняли и почему политические решения могли продолжаться даже при наличии сообщений о тяжёлых последствиях для населения.')],
5:[('Рабочее время и производительность','Рост промышленного выпуска обеспечивался не только новыми станками, но и увеличением числа работников и напряжённости труда. Эти источники роста следует различать: расширение затрат труда не тождественно повышению производительности каждого часа. Стахановское движение с 1935 года создавало образцы рекордов и использовалось для пересмотра норм. Рекорд зависел от подготовки рабочего места и помощи коллектива, поэтому его нельзя механически предъявлять всем работникам как обычную ежедневную возможность. На предприятиях возникали споры о расценках, обеспечении инструментами и справедливости распределения. Они показывают, что за официальной статистикой стоял сложный трудовой процесс.'),('Как сравнивать результаты','Для оценки промышленного скачка можно сопоставлять выпуск оборудования, техническое обучение, структуру занятости и гражданское потребление. Денежные показатели требуют учитывать цены и правила учёта; физические объёмы — качество и ассортимент изделий. Новый завод не сразу достигал проектной мощности, а незавершённая стройка уже поглощала ресурсы. Нельзя судить об эффективности исключительно по существованию построенного объекта: необходим вопрос о затратах и возможных иных способах достижения результата. При этом отрицание насильственных методов не требует отрицать сам факт крупных производственных изменений. Разделение результата и способа его получения делает исторический анализ точнее.')],
8:[('Наука между поддержкой и вмешательством','Развитие промышленности требовало инженеров, исследовательских институтов и технического образования. Государство финансировало крупные проекты и расширяло подготовку специалистов. Однако политические кампании могли определять профессиональную репутацию учёного и допустимость научного направления. Обвинение во вредительстве превращало техническую ошибку в политическое преступление. Поддержка исследований и ограничение интеллектуальной свободы поэтому сосуществовали. Для оценки конкретной области нужно проследить, как принимались научные решения, кто имел возможность возразить и как последствия вмешательства проявлялись в подготовке кадров и качестве знания. Нельзя переносить историю одной дисциплины без проверки на всю советскую науку.'),('Культурная аудитория','Радио, кино, массовая печать и клубы расширяли доступ населения к культурным событиям. Но доступ зависел от электрификации, грамотности, транспортной сети и местной инфраструктуры. Один и тот же фильм в столице и отдалённом поселении мог стать частью совершенно разного зрительского опыта. Официальная аудитория тоже не была пассивной: люди выбирали произведения, обсуждали персонажей и находили собственные смыслы. Поэтому воздействие пропаганды нельзя измерить только тиражом или числом сеансов. Нужно различать распространение сообщения, его понимание и согласие с ним, сопоставляя официальные планы с письмами, отзывами и личными воспоминаниями.')],
9:[('Коминтерн и национальные правительства','Коммунистический интернационал объединял партии, провозглашавшие общую революционную цель. Но отношения между международной организацией, советским государством и отдельными компартиями не оставались неизменными. По мере усиления Москвы внешнеполитические потребности СССР всё заметнее влияли на линию движения. Для иностранных правительств это вызывало подозрение, что дипломатические обещания могут сочетаться с поддержкой внутреннего противника. С другой стороны, нельзя считать любой протест рабочего движения прямым приказом из Москвы. Для конкретного случая нужно устанавливать финансовые, организационные и политические связи, а также самостоятельные интересы местных участников.'),('Пределы дипломатического выигрыша','Договор способен уменьшить непосредственный риск столкновения, но его значение определяется действиями сторон после подписания. В 1930-е годы международные обязательства неоднократно нарушались, а угрозы менялись быстрее, чем согласовывались гарантии. Советское руководство стремилось избежать изоляции, однако его решения влияли и на безопасность соседей. Из этого следует необходимость двух масштабов оценки: собственные расчёты Москвы и последствия для других обществ. Объяснение страхов Сталина и недоверия западных правительств помогает реконструировать выбор, но не заменяет анализа содержания заключённых соглашений. Особенно важно отделять открытые условия договора от секретных территориальных договорённостей.')],
10:[('Почему мировая война имеет несколько хронологий','Европейская дата сентября 1939 года является общепринятой отправной точкой Второй мировой войны, но агрессия Японии в Китае началась раньше. Война стала мировой через соединение конфликтов, имевших различные региональные причины. Поэтому периодизация должна уточнять предмет разговора. Для польской семьи военная катастрофа началась до германского нападения на СССР, а для жителей Китая — ещё до польской кампании. Советская память о 1941–1945 годах отражает решающую для СССР часть войны, но не заменяет общей хронологии. Сопоставление этих рамок расширяет представление о числе участников и разнообразии пережитого опыта.'),('Население разделённой Польши','Раздел польской территории изменил положение поляков, украинцев, белорусов, евреев и других жителей, но их судьбы не были одинаковыми. Люди могли приветствовать конец прежней дискриминации и одновременно оказаться под новым репрессивным давлением. Беженцы двигались между зонами оккупации, зачастую не имея достоверной информации о будущем. Поэтому позднейшее знание о Холокосте нельзя автоматически приписывать каждому решению осени 1939 года. Для описания важны документы о перемещении, арестах, собственности и местной администрации. Они показывают конкретные последствия соглашений, которые на дипломатической карте выглядели лишь проведением новой линии границы.')],
11:[('Судьба присоединённых территорий','Советизация означала изменение собственности, системы управления, образования и политических организаций. Часть населения получала новые возможности, другие теряли имущество, привычные институты и безопасность. Аресты и депортации затрагивали не только лиц, действительно способных организовать сопротивление, но и семьи, выделенные по социальным или политическим признакам. Поэтому формулу о добровольном присоединении нужно проверять по условиям присутствия войск и проведения политических процедур. Международная правовая оценка аннексий и позднейшая советская официальная версия различались. Урок рассматривает это различие как часть истории, а не как основание отказаться от описания документированных действий.'),('Первые часы будущей войны','Боеготовность включала не только доставку приказа, но и вывод частей, организацию связи, прикрытие аэродромов, выдачу боеприпасов и взаимодействие штабов. На огромной границе выполнить эти действия одновременно было трудно. Предвоенные планы отражали представления командования о вероятных направлениях удара, а действительное нападение создало иные условия. Поэтому вопрос «знал ли Сталин?» недостаточен без уточнения, какие меры были приняты после каждого предупреждения. Точно так же факт отдельного предупреждения с ошибочной датой не доказывает недостоверности всех разведывательных сведений. Оценка подготовки требует последовательного разбора решений, времени и их исполнения.')],
13:[('Командование и общественная мобилизация','В Московской битве участвовали несколько фронтов, а устойчивость обороны зависела от взаимодействия штабов и резервов Ставки. Мобилизованные жители рыли противотанковые рвы и строили рубежи, но земляные сооружения были полезны только при наличии вооружённых подразделений, способных их занять. Народное ополчение отражало массовую готовность защищать город и одновременно испытывало недостатки подготовки и вооружения. Эти обстоятельства нужно обсуждать вместе: уважение к участникам не требует скрывать организационные проблемы. Для оценки конкретного соединения важны документы о его формировании, обеспечении и боевом пути, а не общий образ всей битвы.'),('Победа и зимняя кампания','Контрнаступление под Москвой изменило положение на центральном направлении, но не уничтожило все германские группировки. Продолжение ударов зимой сталкивалось с усталостью войск, нехваткой транспорта и снабжения. Советское руководство стремилось развить успех шире, чем позволяли имеющиеся возможности. Это различие между первоначальным успехом и последующим ограничением важно для понимания всей кампании. В мемуарах участники могли подчёркивать либо собственную предусмотрительность, либо ошибки вышестоящего командования. Сопоставление таких оценок с приказами и состоянием частей помогает избежать превращения истории в перечень заранее безошибочных решений победителей.')],
14:[('Неравенство внутри блокадного города','Рабочие, служащие, дети и иждивенцы имели разные нормы карточного снабжения. Доступ к столовой, стационару или помощи учреждения мог существенно изменить шансы выжить. Потеря карточек иногда становилась катастрофой, потому что семья лишалась предусмотренного источника продовольствия. При этом потребности человека определялись не только его официальной категорией: тяжёлая работа, болезнь и необходимость ходить за водой увеличивали расход сил. Изучение распределения не означает обвинения всех выживших в привилегиях. Оно объясняет, почему жители одного города переживали голод по-разному, и помогает увидеть ответственность системы снабжения и пределы её возможностей.'),('Смертность и сохранение свидетельств','Число погибших в блокаде зависит от того, считаются ли только зарегистрированные смерти в городе или также умершие при эвакуации и вскоре после неё. Из-за разрушения семей и учёта часть сведений неполна. В этом уроке не приводится одна точная итоговая цифра без указания метода. Дневники, документы кладбищ и эвакуационные списки отвечают на разные вопросы и должны сопоставляться. Позднейшие воспоминания сохраняют опыт, но иногда объединяют события разных месяцев. Уважение к памяти требует не отказа от проверки, а точного разграничения установленных фактов, оценок и пока не решённых исследовательских вопросов.')],
16:[('Зачем различать уровни результата','Под Прохоровкой конкретное советское соединение могло понести тяжёлые потери, тогда как вся германская операция не достигла поставленной цели. Эти утверждения не противоречат друг другу. Тактика описывает действия подразделений в отдельном бою, оперативный уровень — взаимодействие армий на направлении, стратегия — влияние кампании на продолжение войны. Смешение уровней порождает ложный выбор между прославлением каждого эпизода и отрицанием общей победы. Для проверки важно сначала назвать вопрос, затем выбрать документы соответствующего масштаба. Число уничтоженных машин на одном участке не объясняет автоматически судьбу резервов, коммуникаций и возможностей всего фронта.'),('Инициатива после лета 1943 года','Удержание стратегической инициативы означало возрастающую способность советского командования выбирать направления и время крупных наступлений. Это не означало исчезновения сопротивления или прекращения потерь. Германия сохраняла опытные части и использовала укрепления, а Красная армия училась координировать артиллерию, авиацию, пехоту и подвижные соединения. Дальнейшее продвижение зависело от ремонта техники, восстановления железных дорог и пополнения людей. Поэтому понятие коренного перелома полезно как описание изменения общего соотношения возможностей, но опасно, если превращает последующие два года в якобы лёгкое и заранее завершённое движение к Берлину.')],
17:[('Распределение труда и наказание','Трудовая мобилизация направляла работников туда, где государство видело наибольшую потребность. За самовольный уход и нарушение дисциплины действовали жёсткие наказания. Административная практика различалась по предприятиям и времени, а работники могли жаловаться на невозможные бытовые условия. Необходимо различать добровольное участие в производственной инициативе и отсутствие права покинуть место работы. Оба явления существовали одновременно. История советского тыла не становится точнее ни от полного исключения принуждения, ни от отрицания патриотической мотивации. Документы о нормировании, оплате и дисциплине помогают увидеть, как эти силы соединялись в судьбе конкретного коллектива.'),('Цена восстановления кадров','Во время войны обучение проходило ускоренно и часто непосредственно у станка. Опытный мастер должен был выполнять задание и передавать навыки новичкам, работавшим в условиях усталости и нехватки инструмента. Производственные рекорды могли соседствовать с браком и травматизмом. Поэтому показатель выпуска следует дополнять вопросами о качестве, ремонте и воспроизводстве рабочей силы. Забота о детях при сменной работе требовала общественных служб и семейной взаимопомощи, возможности которых были ограничены. Эти проблемы не были внешним фоном: от их решения зависело, сможет ли промышленность сохранять выпуск оружия на протяжении нескольких лет.')],
18:[('Вывоз на принудительные работы','Оккупационные власти вывозили жителей для работы в Германии и на подконтрольных предприятиях. Обещания заработка сочетались с обманом, облавами и прямым принуждением. Условия труда, питание и правовое положение определялись расовой иерархией нацистского режима. Возвращение после войны не всегда означало немедленное восстановление нормальной жизни: следовали проверки, разлука с семьёй и необходимость доказывать обстоятельства пребывания за границей. Нельзя приравнивать вывезенного работника к добровольному участнику оккупационного аппарата. Для установления судьбы нужны документы отправки, места труда и возвращения, а также личные свидетельства, позволяющие увидеть недоступные ведомственным формам обстоятельства.'),('Сопротивление и национальные движения','На оккупированных землях действовали силы с разными политическими целями, включая советских партизан и движения, ориентированные на собственную государственность. Их отношения могли включать сотрудничество, соперничество и вооружённый конфликт. Название движения само по себе не определяет поведение каждого участника по отношению к гражданским. Для оценки нужно отдельно рассматривать борьбу с оккупантами, участие в этническом насилии и конфликт с советской властью. Такая конкретизация особенно важна для пограничных регионов со сложной довоенной историей. Она не размывает ответственности за преступления, а делает её предметной, связывая вывод с установленными действиями и командными решениями.')]
}
SUPPLEMENT={
1:'В союзных учреждениях объединялись общие задачи, но вопросы языка преподавания и повседневной местной администрации сохраняли республиканское измерение. Поэтому история СССР требует следить и за центральными постановлениями, и за их переводом в местные практики. Одно событие могло восприниматься как объединение, восстановление порядка или утрата независимости разными участниками.',
3:'Особенно важно различать исключение человека из руководства и доказательство ошибочности всех его аргументов. Победа большинства не заменяет проверки хозяйственных предложений. Сохранившиеся документы позволяют сравнивать позиции сторон до разгрома оппозиции, когда дальнейший исход ещё не был известен участникам и не определял их публичные объяснения.',
4:'Единоличная власть опиралась на аппарат, а аппарат нуждался в признанных сигналах допустимого поведения. Устный намёк руководителя мог приобретать вес политического приказа. Такая неопределённость усиливала самоцензуру: чиновник выбирал безопасное действие даже тогда, когда формальная инструкция прямо не требовала запрещать, наказывать или скрывать неудобную информацию.',
5:'Пример Днепрогэса показывает соединение энергетики с промышленным развитием: электричество требовалось крупным предприятиям, а их работа создавала спрос на транспорт и подготовку специалистов. Поэтому отдельную стройку следует рассматривать как часть сети взаимозависимых производств. Отставание одного звена могло ограничить результат уже построенных и торжественно открытых объектов.',
8:'Изменялась и сама культурная карта: новые школы и клубы появлялись в промышленных поселениях, куда недавно приехали сельские жители. Обучение чтению сопровождалось освоением городских правил поведения и новой официальной лексики. Для семьи переход не происходил мгновенно: старые привычки, региональные языки и религиозные представления продолжали влиять на повседневность.',
9:'Советская дипломатия использовала международные площадки и двусторонние договоры по-разному: общая декларация осуждения агрессии не создавала автоматически согласованного военного плана. Надёжность гарантии зависела от готовности партнёров действовать и от согласия государств, через территорию которых предполагалась помощь. Именно эти практические вопросы обостряли споры вокруг коллективной безопасности.',
10:'Объявление войны не равнялось немедленному наступлению всех союзников на равных направлениях. Между юридическим состоянием войны и возможностью провести эффективную операцию лежали мобилизация, подготовка и политические решения. Польская кампания показывает трагические последствия этого разрыва для государства, оказавшегося между двумя вторгшимися армиями и не получившего своевременного военного облегчения.',
11:'Нейтралитет с Японией, оформленный весной 1941 года, уменьшал непосредственную угрозу на дальневосточном направлении, но не давал абсолютной гарантии. Советскому командованию приходилось сохранять там войска и оценивать японские намерения. Подготовка к европейской войне поэтому происходила в условиях необходимости учитывать огромную протяжённость границ и несколько потенциальных противников.',
13:'Оборонявшие Москву войска не состояли только из жителей столицы: соединения прибывали из разных районов многонационального СССР. Переброска требовала железнодорожного транспорта и решения о допустимом ослаблении других направлений. Такой выбор показывает, почему резерв представляет не просто число людей на карте, а результат стратегического распределения ограниченных возможностей государства.',
14:'Детские свидетельства раскрывают разрыв между официальным языком стойкости и повседневной утратой близких. Они не требуют одинакового эмоционального рассказа от каждого ребёнка: молчание, короткая запись и поздняя попытка восстановить события также несут информацию. Сохранение имён, адресов и дат помогает возвращать индивидуальное измерение трагедии, скрытое за общими сводками.',
16:'Авиация также действовала над полем сражения, поддерживая войска и противодействуя противнику. Её эффективность зависела от разведки, связи с наземными частями и состояния аэродромов. Рассказ о Курске как исключительно танковой битве поэтому сужает картину: огонь артиллерии, оборона пехоты и работа инженерных подразделений были столь же необходимыми частями общего замысла.',
17:'Медицинские работники тыла лечили не только боевые ранения, но и последствия истощения и тяжёлого труда. Госпитальная сеть опиралась на здания, персонал и снабжение, которые тоже приходилось перераспределять. Возвращение раненого к жизни и труду было важной составляющей устойчивости общества, хотя такие результаты не выражались напрямую в количестве выпущенных танков.',
18:'Помощь преследуемому могла принимать незаметные формы: ночлег, предупреждение об облаве, передача пищи или укрытие ребёнка. Эти действия не всегда попадали в документы организованного сопротивления. Их изучение расширяет понятие сопротивления за пределы вооружённого отряда, сохраняя различие между индивидуальным спасением людей и операциями военного командования.'
}
SOURCE_MAP={1:['sov-nep-politics','openstax'],3:['sov-succession','sov-nep-politics'],4:['sov-transformation','locarchives'],5:['sov-transformation','sov-stakhanov'],8:['sov-transformation','sov-stakhanov'],9:['sov-pact','sov-nep-politics'],10:['sov-pact','sov-eastfront'],11:['sov-pact','sov-finland-dates'],13:['sov-moscow','warstudy'],14:['sov-eastfront','warstudy'],16:['sov-war-interview','warstudy'],17:['sov-evacuation','warstudy'],18:['sov-eastfront','ushmm']}
def export():
 for id,kind,dates,sections,insight,test,causes in DATA:
  if (ROOT/f'src/content/lessons/{id}.json').exists():continue
  n=int(id[-3:]); allsections=list(sections)+EXTRA.get(n,[])
  allsections[-1]=(allsections[-1][0],allsections[-1][1]+' '+insight+' '+SUPPLEMENT.get(n,''))
  words=sum(len(p.split()) for _,p in allsections)
  if words<500:raise ValueError((id,words,'Добавить предметный текст до500слов'))
  if len(allsections)>7:raise ValueError((id,len(allsections)))
  entry=next(x for x in json.loads((ROOT/'src/content/curriculum.json').read_text()) if x['id']==id)
  simple=(f"Тема «{entry['title']}» объясняет, как решения государства и действия людей меняли советское общество. "+sections[0][1]+' '+insight)
  deep=('Как проверить объяснение',insight+' '+allsections[-1][1].split(insight)[0],causes[0])
  factual,options,answer=test; why,right,wrong=causes
  order_answers=[x[1] for x in dates]
  # Внутри одного года порядок берётся из содержания урока, а не из сортировки цифр.
  questions=[q('single',factual,options,[answer],f'Верный ответ: {answer}. '+sections[1][1]),q('cause',why,[right,wrong],[right],right+'. '+insight),q('order','Расположите этапы темы в последовательности, объяснённой в уроке.',list(reversed(order_answers)),order_answers,'Последовательность связывает предпосылки, развитие и результат: '+' → '.join(order_answers)+'.'),q('text',f"Объясните связь между событиями темы «{entry['title']}» и их последствиями для людей. Назовите один механизм и один предел обобщения.",None,[insight],insight+' '+sections[-1][1],selfAssessed=True)]
  body='\n## '.join(t+'\n'+p for t,p in allsections)
  add(id,entry['title']+': причины, последовательность решений, общественные последствия и пределы исторической оценки.',[f"Объяснять причины и ход событий темы «{entry['title']}»",'Сопоставлять государственные решения с последствиями для разных групп населения'],simple,body,deep,[sections[0][1].split('. ')[0]+'.',sections[2][1].split('. ')[0]+'.',insight],[(y,t,'Опорная дата; см. объяснение в основном тексте.','Политика' if kind not in ('war','socwar') else 'Войны') for y,t in dates],[],[],[],SOURCE_MAP[n],questions)
if __name__=='__main__':export()
